<?php
declare(strict_types=1);
header('X-Content-Type-Options: nosniff');header('Cache-Control: no-store');
$ip=$_SERVER['REMOTE_ADDR']??'';
if(!preg_match('/^(127\\.0\\.0\\.1|::1|192\\.168\\.(5|10|21|200)\\.[0-9]{1,3})$/',$ip)){http_response_code(403);exit('LAN only');}
$db=pg_connect('dbname=bf4_battle_reports user=www-data');if(!$db){http_response_code(503);exit('DB unavailable');}
function rows($db,$q){$r=pg_query($db,$q);if(!$r)throw new RuntimeException();return pg_fetch_all($r)?:[];}
if(isset($_GET['json'])){header('Content-Type: application/json');try{
pg_query($db,"SET statement_timeout='3000ms'");
echo json_encode(['time'=>gmdate('c'),
'personas'=>rows($db,"SELECT j.platform,j.persona_id,coalesce(p.current_name,'Unknown') name,j.lease_owner,j.updated_at FROM bf4br_persona_jobs j LEFT JOIN players p ON p.platform=j.platform AND p.persona_id=j.persona_id WHERE j.state='leased' AND j.lease_until>now() ORDER BY j.platform,j.lease_owner LIMIT 100"),
'jobs'=>rows($db,"SELECT platform,battlelog_report_id,lease_owner,updated_at FROM bf4br_report_jobs WHERE state='leased' AND lease_until>now() ORDER BY platform,lease_owner LIMIT 100"),
'new'=>rows($db,"SELECT r.platform,r.battlelog_report_id,r.imported_at,d.report_timestamp AS match_timestamp FROM battle_report_raw r LEFT JOIN history_discoveries d ON d.platform=r.platform AND d.battlelog_report_id=r.battlelog_report_id WHERE r.imported_at IS NOT NULL ORDER BY r.imported_at DESC LIMIT 60"),
'counts'=>rows($db,"SELECT platform,count(*) n FROM battle_report_raw WHERE imported_at>now()-interval '10 minutes' GROUP BY platform")],JSON_INVALID_UTF8_SUBSTITUTE);
}catch(Throwable $e){http_response_code(503);echo '{"error":"Monitoring unavailable"}';}exit;}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Live Collection | BF4 Battle Reports</title><style>
*{box-sizing:border-box}body{background:#0c121b;color:#e6edf7;font:14px/1.5 system-ui;margin:0}.wrap{max-width:1500px;margin:auto;padding:24px}a{color:#8ec8ff;text-decoration:none}a:hover{text-decoration:underline}header{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;border-bottom:1px solid #35465b;padding-bottom:20px}nav{display:flex;gap:18px;flex-wrap:wrap}.brand{font-size:23px;font-weight:800}.brand span{color:#f4a24c}h1{font-size:29px;margin-bottom:3px}.muted{color:#9db1c7}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:20px 0}.card,.panel{background:#142233;border:1px solid #31445b;border-radius:12px;padding:16px}.card strong{display:block;font-size:28px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.panel{min-width:0;margin-bottom:16px}h2{font-size:18px;margin:0 0 12px}.scroll{max-height:520px;overflow:auto}table{border-collapse:collapse;width:100%;text-align:left}th{position:sticky;top:0;background:#20354b;color:#adc0d3}td,th{padding:9px;border-bottom:1px solid #304156;white-space:nowrap}td.name{white-space:normal;overflow-wrap:anywhere}.pc{color:#f6b56d}.ps{color:#82baff}.xb{color:#80e6a3}button{background:#233b55;border:1px solid #58718c;color:white;border-radius:6px;padding:8px 12px;cursor:pointer}@media(max-width:850px){.grid{grid-template-columns:1fr}.cards{grid-template-columns:repeat(2,1fr)}} 
</style></head><body><div class="wrap"><header><div class="brand">BF4 <span>BATTLE REPORTS</span></div><nav><a href="battle-reports.php">Archive</a><a href="shared-reports.php">Shared-player search</a><a href="discovery-control.php">Player discovery</a><a href="battle-reports-live.php">Live collection</a></nav></header><h1>Live collection monitor</h1><p class="muted">Current worker leases and incoming battle reports · automatically refreshes every 5 seconds</p><button id="toggle">Pause updates</button> <span id="status" class="muted">Connecting…</span>
<div class="cards"><div class="card">Active persona jobs<strong id="pc">—</strong></div><div class="card">Active report jobs<strong id="rc">—</strong></div><div class="card">Imported in 10 minutes<strong id="ic">—</strong></div><div class="card">Latest import<strong id="age">—</strong></div></div>
<div class="grid"><section class="panel"><h2>Personas currently being processed</h2><div class="scroll"><table><thead><tr><th>Platform</th><th>Player name</th><th>Persona ID</th><th>Worker</th><th>Claimed (UTC)</th></tr></thead><tbody id="personas"></tbody></table></div></section><section class="panel"><h2>Reports currently being processed</h2><div class="scroll"><table><thead><tr><th>Platform</th><th>Report ID</th><th>Worker</th><th>Claimed (UTC)</th></tr></thead><tbody id="jobs"></tbody></table></div></section></div>
<section class="panel"><h2>Incoming battle reports · latest 60</h2><div class="scroll"><table><thead><tr><th>Imported (UTC)</th><th>Match played (UTC)</th><th>Platform</th><th>Report ID</th><th>Scoreboard</th></tr></thead><tbody id="new"></tbody></table></div></section><p class="muted">A lease means a worker claimed the job, not necessarily that a network request is underway. Match dates come from locally recorded Battlelog discovery timestamps; missing timestamps display a dash. Names reflect the latest locally recorded player name. LAN access only.</p></div>
<script>
const el=id=>document.getElementById(id),names={1:'PC',32:'PlayStation',64:'Xbox'},cls={1:'pc',32:'ps',64:'xb'};let paused=false,busy=false,last=null;
const safe=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const plat=v=>'<span class="'+(cls[v]||'')+'">'+safe(names[v]||v)+'</span>';
const date=v=>v?new Date(v).toISOString().slice(0,19).replace('T',' ')+' UTC':'—';
const age=v=>{if(!v)return '—';let s=Math.max(0,Math.floor((Date.now()-Date.parse(v))/1000));return s<60?s+'s ago':Math.floor(s/60)+'m ago';};
function fill(id,data,fn,cols){el(id).innerHTML=data.length?data.map(fn).join(''):'<tr><td colspan="'+cols+'" class="muted">No active jobs</td></tr>';}
function render(d){el('pc').textContent=d.personas.length;el('rc').textContent=d.jobs.length;el('ic').textContent=d.counts.reduce((a,x)=>a+Number(x.n),0);last=d.new[0]?.imported_at||null;el('age').textContent=age(last);
fill('personas',d.personas,r=>'<tr><td>'+plat(r.platform)+'</td><td class="name">'+safe(r.name)+'</td><td><a href="battle-reports.php?persona='+encodeURIComponent(r.persona_id)+'&platform='+encodeURIComponent(r.platform)+'">'+safe(r.persona_id)+'</a></td><td>'+safe(r.lease_owner)+'</td><td>'+date(r.updated_at)+'</td></tr>',5);
fill('jobs',d.jobs,r=>'<tr><td>'+plat(r.platform)+'</td><td>'+safe(r.battlelog_report_id)+'</td><td>'+safe(r.lease_owner)+'</td><td>'+date(r.updated_at)+'</td></tr>',4);
fill('new',d.new,r=>'<tr><td>'+date(r.imported_at)+'</td><td>'+date(r.match_timestamp)+'</td><td>'+plat(r.platform)+'</td><td>'+safe(r.battlelog_report_id)+'</td><td><a href="battle-reports.php?report='+encodeURIComponent(r.battlelog_report_id)+'&platform='+encodeURIComponent(r.platform)+'">View scoreboard →</a></td></tr>',4);
el('status').textContent='Live · updated '+new Date().toLocaleTimeString();}
async function refresh(){if(paused||busy||document.hidden)return;busy=true;let ctl=new AbortController(),timeout=setTimeout(()=>ctl.abort(),4500);try{let r=await fetch('battle-reports-live.php?json=1',{cache:'no-store',signal:ctl.signal});if(!r.ok)throw Error('HTTP '+r.status);render(await r.json());}catch(e){el('status').textContent='Connection issue: '+e.message;}finally{clearTimeout(timeout);busy=false;}}
el('toggle').onclick=()=>{paused=!paused;el('toggle').textContent=paused?'Resume updates':'Pause updates';if(paused)el('status').textContent='Paused';else refresh();};setInterval(refresh,5000);setInterval(()=>{if(last)el('age').textContent=age(last);},1000);refresh();
</script></body></html>
